import 'package:flutter/material.dart'; import 'package:flutter_test/flutter_test.dart'; import 'package:mobile/core/theme/app_theme.dart'; import 'package:mobile/features/chatbot/models/chatbot_models.dart'; import 'package:mobile/features/chatbot/widgets/chat_results_map.dart';
void main() { testWidgets('mapped results render OSM markers and skip missing coordinates', (tester) async { String? selected; await tester.pumpWidget(MaterialApp(theme: AppTheme.light(), home: Scaffold(body: ChatResultsMap(places: const [ChatPlaceResult(id: 'mapped', nameEn: 'Mapped clinic', latitude: 32.22, longitude: 35.25), ChatPlaceResult(id: 'missing', nameEn: 'Missing')], clinics: const [], doctors: const [], selectedId: selected, onSelected: (id) => selected = id)))); await tester.pump(); expect(find.byKey(const ValueKey('discovery-map-place-place-mapped')), findsOneWidget); expect(find.byKey(const ValueKey('discovery-map-place-place-missing')), findsNothing); expect(find.byKey(const ValueKey('osm-attribution')), findsOneWidget); }); }
